import {getLanguage} from './locales/locale.mjs';
const t=(zh,en)=>getLanguage()==='en'?en:zh;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attr,zh,en)=>`<button class="text-button" ${attr}>${t(zh,en)} ↗</button>`;

export function strategyLearning(researchDate,snapshotAt){
 const branches=[
  [t('利好得到经营证据支持','Positive business evidence'),t('估值中枢上移','Valuation moves up'),t('重新安排 LP 区间，偏向保留股票','Reconsider LP ranges and retain more shares'),'up'],
  [t('没有实质变化／证据不足','No material change / insufficient evidence'),t('估值保持不变','Valuation stays unchanged'),t('继续原策略，保留观察事项','Keep the strategy and monitor open questions'),'neutral'],
  [t('利空确认影响经营','Negative business impact confirmed'),t('估值中枢下移','Valuation moves down'),t('退出旧区间，减少股票、保留现金','Exit old ranges, reduce shares and retain cash'),'down']
 ];
 return `<section class="panel principle-revision"><div class="plan-stage-heading"><span class="step-number">03</span><h2>${t('事实变化时，AI 修正估值与持仓','When facts change, AI revises value and positions')}</h2></div><p>${t('持续跟踪新闻、财报、公开披露的内部人交易及经营数据。先核实变化是否影响公司赚钱的能力，再检查估值与现有持仓是否需要一起调整。','Follow news, filings, publicly disclosed insider transactions and operating data. First check whether the change affects the business, then review valuation and existing positions together.')}</p>
 <div class="revision-method"><div><b>${t('核实新事实','Verify new facts')}</b><span>${t('来源、日期与经营影响','Sources, dates and business impact')}</span></div><i>→</i><div><b>${t('更新估值假设','Update valuation assumptions')}</b><span>${t('规模、利润、倍数与风险','Scale, earnings, multiples and risk')}</span></div><i>→</i><div><b>${t('对照当前仓位','Review current holdings')}</b><span>${t('LP 区间、股票与现金','LP ranges, shares and cash')}</span></div></div>
 <div class="revision-branches" aria-label="${t('事实与策略响应示意','Illustrative fact-to-strategy responses')}">${branches.map(([fact,value,action,kind])=>`<div class="revision-branch ${kind}"><span>${fact}</span><b>${value}</b><p>${action}</p></div>`).join('')}</div>
 <p class="flow-caption">${t('上述是模拟中三种事件的响应原理。实际修正取决于证据与持仓约束；一条消息并不直接触发交易。','These illustrate the three simulated event responses. Actual revisions depend on evidence and position constraints; a headline alone does not trigger a trade.')}</p>
 <div class="archived-review-note"><div class="row"><b>${t('已有跟踪案例：观察，暂不修正','Archived example: watch, no revision yet')}</b><small>${esc(researchDate)}</small></div><p>${t('稳定币监管线索尚未获得足够的官方经营影响证据，因此保留观察、维持原估值。持续跟踪也包括判断什么时候不需要改变。','A stablecoin regulatory signal lacked sufficient official evidence of business impact. The case remained under observation with valuation unchanged. Monitoring also means deciding when no change is warranted.')}</p>${button('data-detail="research"','回看核实过程与结论','Review the evidence and conclusion')}</div>
 <div class="flow-doc-links">${button('data-review','体验一次 AI 修正','Try an AI revision')}${button('data-proof="candidates"','查看估值修正与配仓依据','See the revision and allocation reasoning')}</div></section>
 <div class="plan-ai-bridge"><span>${t('建议与实际仓位留下记录','Record proposals and actual positions')}</span><i>↓</i><span>${t('用结果复核判断，而不只看一次盈亏','Review the reasoning through outcomes over time')}</span></div>
 <section class="panel principle-iteration"><div class="plan-stage-heading"><span class="step-number">04</span><h2>${t('记录结果，反馈到下一轮迭代','Record outcomes and improve the next iteration')}</h2></div><p>${t('每次仓位变化都能回看当时依据；净值与收益持续记录。把结果拆开，识别偏差来自判断、持仓规则还是数据与执行，再形成下一轮改进。','Keep the reasoning behind position changes alongside NAV and return records. Separate the outcomes to identify whether discrepancies come from the thesis, position rules, data or execution, then propose improvements.')}</p>
 <div class="iteration-stages"><div><span>01</span><h3>${t('记录仓位与净值','Record positions and NAV')}</h3><p>${t('保留股票、现金、LP 区间、费用与操作时点，形成可追溯的历史。','Retain shares, cash, LP ranges, fees and action timestamps in a traceable history.')}</p></div><div><span>02</span><h3>${t('拆解收益与偏差','Attribute returns and discrepancies')}</h3><p>${t('对比纯持股，区分持股涨跌、手续费和区间管理的贡献，找出多赚或少赚的原因。','Compare against holding shares and separate price exposure, fees and range-management contributions to explain differences.')}</p></div><div><span>03</span><h3>${t('改进策略与产品','Refine strategy and product')}</h3><p>${t('复核估值因子、调仓条件与资金安排，也检查取数和展示口径。修改经验证与确认后保留新版本。','Review valuation factors, rebalance triggers, allocation, data inputs and presentation. Validate and confirm changes, then retain a new version.')}</p></div></div>
 <div class="iteration-feedback"><b>${t('结果反馈 → 下一轮估值、配仓与跟踪','Feedback → the next valuation, allocation and monitoring cycle')}</b><span>${t('保留依据、记录偏差、验证修改；迭代不等于每次都能提高收益。','Keep evidence, record discrepancies and validate changes. An iteration does not guarantee a better return.')}</span></div>
 <div class="iteration-records"><small>${t('实盘记录截至','Live records through')} ${esc(snapshotAt.slice(0,10))}</small><div>${button('data-doc="pnl_latest"','查看 PNL 日报 · 2026-09-18','Read P&L report · 2026-09-18')}${button('data-proof="runs"','查看运行与复核记录','Inspect run and review records')}</div></div>
 <p class="flow-caption">${t('这里展示研究、核算与复盘的工作流程。交互体验复用已准备的 AI 方案，不实时调用 AI，也不会自行修改规则或执行交易。','This presents the research, accounting and review workflow. The interactive demo reuses prepared AI proposals; it does not call AI live, rewrite rules or execute trades.')}</p></section>`;
}
